package com.gerenciadorrural.modules.finance.api;
import com.gerenciadorrural.modules.finance.application.FinanceService.*; import com.gerenciadorrural.shared.api.error.ApiErrorResponse; import com.gerenciadorrural.shared.observability.RequestContextFilter; import jakarta.servlet.http.HttpServletRequest; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestControllerAdvice(assignableTypes=FinanceController.class) class FinanceExceptionHandler {private ResponseEntity<ApiErrorResponse> e(HttpStatus s,String code,HttpServletRequest r){Object id=r.getAttribute(RequestContextFilter.REQUEST_ID_ATTRIBUTE);return ResponseEntity.status(s).cacheControl(CacheControl.noStore()).body(new ApiErrorResponse(code,"A operação financeira não pôde ser concluída",s.value(),id==null?null:id.toString(),List.of(),Instant.now()));}@ExceptionHandler(Invalid.class)ResponseEntity<ApiErrorResponse> invalid(HttpServletRequest r){return e(HttpStatus.BAD_REQUEST,"FINANCE_COMMAND_INVALID",r);}@ExceptionHandler(Forbidden.class)ResponseEntity<ApiErrorResponse> forbidden(HttpServletRequest r){return e(HttpStatus.FORBIDDEN,"FINANCE_FORBIDDEN",r);}@ExceptionHandler(CategoryNotFound.class)ResponseEntity<ApiErrorResponse> category(HttpServletRequest r){return e(HttpStatus.NOT_FOUND,"FINANCE_CATEGORY_NOT_FOUND",r);}@ExceptionHandler(EntryNotFound.class)ResponseEntity<ApiErrorResponse> entry(HttpServletRequest r){return e(HttpStatus.NOT_FOUND,"FINANCE_ENTRY_NOT_FOUND",r);}@ExceptionHandler(Idempotency.class)ResponseEntity<ApiErrorResponse> idem(HttpServletRequest r){return e(HttpStatus.CONFLICT,"FINANCE_OPERATION_IDEMPOTENCY_CONFLICT",r);}@ExceptionHandler(Conflict.class)ResponseEntity<ApiErrorResponse> conflict(HttpServletRequest r){return e(HttpStatus.CONFLICT,"FINANCE_ENTRY_CONFLICT",r);}}
